begin;

-- AFLP Sustainability operational catalog v2026.2.
-- Keep 2026.1 for historical readability; new baselines/inspections use 2026.2.
on conflict (question_code,catalog_version) do update set
 domain=excluded.domain, sequence_no=excluded.sequence_no, label_fr=excluded.label_fr, label_en=excluded.label_en,
 guidance_fr=excluded.guidance_fr, required=excluded.required, risk_trigger_answers=excluded.risk_trigger_answers,
 risk_level=excluded.risk_level, default_corrective_action=excluded.default_corrective_action,
 default_priority=excluded.default_priority, active=excluded.active, updated_at=now();

alter table public.farmer_sustainability_baselines alter column catalog_version set default 'AFLP-SUST-2026.2';
alter table public.farmer_inspections alter column catalog_version set default 'AFLP-SUST-2026.2';

commit;
